<?phpif (!defined('BASEPATH')) {	exit('No direct script access allowed');}include_once APPPATH . '/modules/layout/controllers/Layout.php';class Pay extends Layout {	private $_module_slug = 'tra-tien-no';	private $_module_name = 'công nợ khách hàng';	function __construct() {		parent::__construct();		$this->_data['breadcrumbs_module_name'] = ucfirst($this->_module_name);		$this->_data['breadcrumbs_module_func'] = 'Danh sách';		$this->_data['module_slug'] = $this->_module_slug;		$this->_data['module_name'] = $this->_module_name;		$_breadcrumbs_admin[] = array(			'url' => '',			'name' => 'Công nợ khách hàng',			'image' => base_url('assets/Frest/app-assets/images/svg/ico/ico-output-product.svg'),		);		$this->set_breadcrumbs_admin();	}	private function _validate_access_role(){		$this->validate_access_role('ROLE_GROUP_PAY');	}	function default_args() {		$order_by = array(			'created' => 'DESC',			'modified' => 'DESC',		);		$args = array();		$args['order_by'] = $order_by;		return $args;	}	function counts($options = array()) {		$default_args = $this->default_args();		if (is_array($options) && !empty($options)) {			$args = array_merge($default_args, $options);		} else {			$args = $default_args;		}		return $this->M_pay->counts($args);	}	function gets($options = array()) {		$default_args = $this->default_args();		if (is_array($options) && !empty($options)) {			$args = array_merge($default_args, $options);		} else {			$args = $default_args;		}		return $this->M_pay->gets($args);	}	function get($id) {		return $this->M_pay->get($id);	}	function add($data) {		if (!is_array($data) || empty($data)) {			return 0;		}		return $this->M_pay->add($data);	}	function update($id, $data) {		if (!is_array($data) || empty($data)) {			return 0;		}		return $this->M_pay->update($id, $data);	}	function check_quantity_availablity() {		$post = $this->input->post();		$this->_message_success = 'true';		$this->_message_danger = 'false';		if (!empty($post)) {			$customer_id = (int) $this->input->post('customer_id');			$customer = modules::run('customers/get', $customer_id);			if(!(is_array($customer) && !empty($customer))){				$this->_status = "danger";				$this->_message = $this->_message_danger;				$this->_content = NULL;			}else {							$arrears = $customer['arrears'];				$total = $this->input->post('amount');				$remainder = $arrears - $total;				if($remainder >= 0){					$this->_status = "success";					$this->_message = $this->_message_success;					$this->_content = array(						'arrears' => $arrears,						'total' => $total,						'remainder' => $remainder,					);				} else {					$this->_status = "danger";					$this->_message = $this->_message_danger;					$this->_content = isset($customer) ? $customer : NULL;				}							}			$this->set_json_encode();			$this->load->view('layout/json_data', $this->_data);		} else {			redirect(base_url());		}	}	function admin_view() {		$this->_initialize_admin();		$this->_validate_access_role();		$id = (int) (($this->uri->segment(3) == '') ? 0 : $this->uri->segment(3));		if ($id == 0) {			show_404();		}		$this->_data['current_page'] = (int) $this->input->get('current_page');		$row = $this->get($id);		$this->_data['row'] = $row;		$this->_data['breadcrumbs_module_func'] = 'Xem thông tin ' . $this->_module_name;		$this->_data['title'] = 'Xem thông tin ' . $this->_module_name . ' - ' . $this->_data['breadcrumbs_module_name'];		$this->_data['main_content'] = 'admin/view_page_view';		$this->load->view('layout/admin/view_layout', $this->_data);	}	function admin_index() {		$this->_initialize_admin();		$this->_validate_access_role();		$this->_module_slug = 'cong-no-khach-hang/lich-su-tra-tien-no';		$this->_data['module_slug'] = $this->_module_slug;		$this->_plugins_css_admin[] = array(			'folder' => 'bootstrap4-dialog/css',			'name' => 'bootstrap-dialog',		);		$this->_plugins_script_admin[] = array(			'folder' => 'bootstrap4-dialog/js',			'name' => 'bootstrap-dialog',		);		$this->set_plugins_admin();		$this->_modules_script[] = array(			'folder' => 'pay',			'name' => 'admin-items',		);		$this->set_modules();		$customer_id = (int) $this->input->get('customer_id');		$customer = modules::run('customers/get', $customer_id);		if(!(is_array($customer) && !empty($customer))){			$notify_type = 'danger';			$notify_content = 'Khách hàng này không tồn tại!';			$this->set_notify_admin($notify_type, $notify_content);			redirect(site_url('cong-no-khach-hang'));		}		$this->_data['customer'] = $customer;		$get = $this->input->get();		$this->_data['get'] = $get;		$args = $this->default_args();		$args['customer_id'] = $customer_id;		if (isset($get['q']) && trim($get['q']) != '') {			$args['q'] = $get['q'];		}		$total = $this->counts($args);		$perpage = isset($get['per_page']) ? $get['per_page'] : $this->config->item('per_page');		$segment = 2;		$this->load->library('pagination');		$config['total_rows'] = $total;		$config['per_page'] = $perpage;		$config['full_tag_open'] = '<ul class="pagination no-margin pull-right">';		$config['full_tag_close'] = '</ul>';		$config['first_link'] = '&laquo;';		$config['first_tag_open'] = '<li class="prev page">';		$config['first_tag_close'] = '</li>';		$config['last_link'] = '&raquo;';		$config['last_tag_open'] = '<li class="next page">';		$config['last_tag_close'] = '</li>';		$config['next_link'] = 'Trang trước &rarr;';		$config['next_tag_open'] = '<li class="next page">';		$config['next_tag_close'] = '</li>';		$config['prev_link'] = '&larr; Trang sau';		$config['prev_tag_open'] = '<li class="prev page">';		$config['prev_tag_close'] = '</li>';		$config['cur_tag_open'] = '<li class="active"><a href="">';		$config['cur_tag_close'] = '</a></li>';		$config['num_tag_open'] = '<li class="page">';		$config['num_tag_close'] = '</li>';		if (!empty($get)) {			$config['base_url'] = base_url($this->_module_slug);			$config['suffix'] = '?' . http_build_query($get, '', "&");			$config['first_url'] = base_url($this->_module_slug . '?' . http_build_query($get, '', "&"));			$config['uri_segment'] = $segment;		} else {			$config['base_url'] = base_url($this->_module_slug);			$config['uri_segment'] = $segment;		}		$this->pagination->initialize($config);		$pagination = $this->pagination->create_links();		$this->_data['pagination'] = $pagination;		$offset = ($this->uri->segment($segment) == '') ? 0 : $this->uri->segment($segment);		$rows = $this->M_pay->gets($args, $perpage, $offset);		$this->_data['rows'] = $rows;		$this->_data['title'] = 'Lịch sử trả tiền - Công nợ khách hàng: ' . $customer['full_name'] . ' - ' . $this->_data['title'];		$this->_data['main_content'] = 'admin/view_page_index';		$this->load->view('layout/admin/view_layout', $this->_data);	}	function admin_add() {		$time = time();		$date = $this->input->post('date');		$data = array(			'admin_id' => $this->_data['userid'],			'customer_id' => $this->input->post('customer_id'),			'amount' => $this->input->post('amount'),			'date' => (trim($date) != '') ? get_current_date($date) : $time,			'note' => $this->input->post('note'),			'created' => $time,			'modified' => 0,			'status' => 1,		);		return $this->add($data);	}	function admin_update($id) {		$time = time();		$date = $this->input->post('date');		$data = array(			'customer_id' => $this->input->post('customer_id'),			'amount' => $this->input->post('amount'),			'date' => (trim($date) != '') ? get_current_date($date) : $time,			'note' => $this->input->post('note'),			'modified' => $time,		);		return $this->update($id, $data);	}	function admin_delete() {		$this->_initialize_admin();		$this->_validate_access_role();		$this->_message_success = 'Đã xóa ' . $this->_module_name . '!';		$this->_message_warning = ucfirst($this->_module_name) . ' này không tồn tại!';		$id = $this->input->get('id');		if ($id != 0) {			if ($this->M_pay->delete($id)) {				$notify_type = 'success';				$notify_content = $this->_message_success;			} else {				$notify_type = 'danger';				$notify_content = $this->_message_danger;			}		} else {			$notify_type = 'warning';			$notify_content = $this->_message_warning;		}		$this->set_notify_admin($notify_type, $notify_content);		redirect(base_url($this->_module_slug));	}	function admin_main() {		$this->_initialize_admin();		$this->_validate_access_role();		$post = $this->input->post();		if (!empty($post)) {			$action = $this->input->post('action');			if ($action == 'delete') {				$this->_message_success = 'Đã xóa các ' . $this->_module_name . ' được chọn!';				$this->_message_warning = 'Bạn chưa chọn ' . $this->_module_name . ' nào!';				$ids = $this->input->post('idcheck');				if (is_array($ids) && !empty($ids)) {					foreach ($ids as $id) {						if ($this->M_pay->delete($id)) {							$notify_type = 'success';							$notify_content = $this->_message_success;						} else {							$notify_type = 'danger';							$notify_content = $this->_message_danger;						}					}				} else {					$notify_type = 'warning';					$notify_content = $this->_message_warning;				}				$this->set_notify_admin($notify_type, $notify_content);				redirect(base_url($this->_module_slug));			} elseif ($action == 'content') {				redirect(base_url($this->_module_slug . '/them'));			}		} else {			redirect(base_url($this->_module_slug));		}	}	function admin_content() {		$this->_initialize_admin();		$this->_validate_access_role();		$this->_plugins_css_admin[] = array(			'folder' => 'bootstrap-datepicker/css',			'name' => 'bootstrap-datepicker',		);		$this->_plugins_css_admin[] = array(			'folder' => 'bootstrap-datepicker/css',			'name' => 'bootstrap-datepicker3',		);		$this->_plugins_script_admin[] = array(			'folder' => 'bootstrap-datepicker/js',			'name' => 'bootstrap-datepicker',		);		$this->_plugins_script_admin[] = array(			'folder' => 'bootstrap-datepicker/locales',			'name' => 'bootstrap-datepicker.vi.min',		);		$this->_plugins_script_admin[] = array(			'folder' => 'bootstrap-datepicker',			'name' => 'app.editinfo',		);		$this->_plugins_script_admin[] = array(			'folder' => 'jquery-validation',			'name' => 'jquery.validate',		);		$this->_plugins_script_admin[] = array(			'folder' => 'jquery-validation/localization',			'name' => 'messages_vi',		);		$this->set_plugins_admin();		$this->_modules_script[] = array(			'folder' => 'pay',			'name' => 'admin-validate-content',		);		$this->set_modules();		$this->_module_slug = 'cong-no-khach-hang';		$customer_id = (int) $this->input->get('customer_id');		$customer = modules::run('customers/get', $customer_id);		if(!(is_array($customer) && !empty($customer))){			$notify_type = 'danger';			$notify_content = 'Khách hàng này không tồn tại!';			$this->set_notify_admin($notify_type, $notify_content);			redirect(base_url($this->_module_slug));		}				$arrears = $customer['arrears'];		if($arrears == 0){			$notify_type = 'danger';			$notify_content = 'Không thể thanh toán công nợ cho khách hàng này! Vui lòng kiểm tra lại!';			$this->set_notify_admin($notify_type, $notify_content);			redirect(base_url($this->_module_slug));		}		$customers = array($customer);				$paid = $this->M_pay->get_paid(array('customer_id' => $customer_id));		$this->_data['customers'] = $customers;		$this->_data['arrears'] = $arrears;		$this->_data['readonly'] = ' readonly';		$post = $this->input->post();		if (!empty($post)) {			$this->form_validation->set_error_delimiters('<span class="help-block">', '</span>');			$this->form_validation->set_rules('amount', 'Số tiền trả', 'trim|required');			if ($this->form_validation->run($this)) {				$amount = (float) $this->input->post('amount');				if($amount > $arrears){					$notify_type = 'danger';					$notify_content = 'Thanh toán công nợ tối đa của khách hàng này là ' . $arrears . '! Vui lòng kiểm tra lại!';					$this->set_notify_admin($notify_type, $notify_content);					redirect(current_full_url());				}				$insert_id = $this->admin_add();				if ($insert_id != 0) {					$this->M_customers->update($customer_id, array('arrears' => $arrears - $amount));					$notify_type = 'success';					$notify_content = 'Thanh toán công nợ thành công!';					$this->set_notify_admin($notify_type, $notify_content);					redirect(base_url($this->_module_slug));				} else {					$notify_type = 'danger';					$notify_content = 'Có lỗi xảy ra!';					$this->set_notify_admin($notify_type, $notify_content);				}			}		}		$this->_data['title'] = 'Thanh toán công nợ - Khách hàng: ' . $customer['full_name'] . ' - ' . $this->_data['title'];		$this->_data['main_content'] = 'admin/view_page_content';		$this->load->view('layout/admin/view_layout', $this->_data);	}}/* End of file Pay.php *//* Location: ./application/modules/pay/controllers/Pay.php */